  style.dataset.plugin = "dsh-openui";
  style.dataset.pluginCss = id2;
  style.textContent = '.dsh-openui-card {\n  --openui-font-body: var(--dsw-font-family, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif);\n  --openui-foreground: var(--dsw-alias-bg-base, #fff);\n  --openui-text-neutral-primary: var(--dsw-alias-label-primary, #171717);\n  --openui-text-neutral-secondary: var(--dsw-alias-label-secondary, rgb(0 0 0 / 62%));\n  width: 100%;\n  margin: 0;\n  border: 1px solid var(--dsw-alias-border-l2, rgb(0 0 0 / 10%));\n  border-radius: var(--dsw-radius-panel, 16px);\n  background: var(--dsw-alias-bg-base, #fff);\n  color: var(--dsw-alias-label-primary, #171717);\n  overflow: hidden;\n}\n\n.dsh-openui-card,\n.dsh-openui-card *,\n.dsh-openui-card *::before,\n.dsh-openui-card *::after {\n  box-sizing: border-box;\n}\n\n.dsh-openui-portal {\n  --dsh-chat-flow-gap: 12px;\n  width: 100%;\n  max-width: 100%;\n  min-width: 0;\n}\n\n.dsh-openui-tool-status {\n  color: var(--dsw-alias-label-caption, #888);\n  font-size: var(--dsh-content-font-size-secondary, 13px);\n  line-height: 20px;\n}\n\n.dsh-openui-head {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  min-height: 38px;\n  padding: 0 14px;\n  border-bottom: 1px solid var(--dsw-alias-border-l2, rgb(0 0 0 / 8%));\n  color: var(--dsw-alias-label-secondary, #666);\n  font-size: 12px;\n}\n\n.dsh-openui-head strong {\n  color: var(--dsw-alias-label-primary, #171717);\n  font-size: 13px;\n  font-weight: 560;\n}\n\n.dsh-openui-live {\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n  background: var(--dsw-alias-state-business-primary, #5f8ff7);\n  animation: dsh-openui-pulse 1s ease-in-out infinite alternate;\n}\n\n.dsh-openui-body {\n  padding: 18px;\n  overflow-x: auto;\n}\n\n.dsh-openui-empty {\n  padding: 22px 18px;\n  color: var(--dsw-alias-label-caption, #888);\n  font-size: 13px;\n}\n\n.dsh-openui-source {\n  border-top: 1px solid var(--dsw-alias-border-l2, rgb(0 0 0 / 8%));\n}\n\n.dsh-openui-source summary {\n  cursor: pointer;\n  padding: 9px 14px;\n  color: var(--dsw-alias-label-caption, #888);\n  font-size: 12px;\n}\n\n.dsh-openui-source pre {\n  max-height: 320px;\n  margin: 0;\n  padding: 0 14px 14px;\n  overflow: auto;\n  white-space: pre-wrap;\n  color: var(--dsw-alias-label-secondary, #666);\n  font: 12px/1.55 var(--ds-font-family-code, ui-monospace, monospace);\n}\n\n@keyframes dsh-openui-pulse {\n  from { opacity: .35; }\n  to { opacity: 1; }\n}\n';
